--[[ENRIQUE FREE | Fast Stream Runtime v23]]
local _ok, _err = pcall(function()
local bit32 = bit32
if not bit32 then error("bit32 missing") end
local band, bor, bxor, lshift, rshift = bit32.band, bit32.bor, bit32.bxor, bit32.lshift, bit32.rshift
local M, key = {}, {}
local A = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
for i = 1, #A do M[A:byte(i)] = i - 1 end
M[61] = 0
for i = 0, 95 do
    local left = band(i * 181 + 37, 255)
    local right = band(rshift(0xA53F91C7, band(i * 7, 31)), 255)
    key[i + 1] = bxor(left, right)
end

local P = {}
P[1] = [========[]========]
P[2] = [========[]========]
P[3] = [========[]========]
P[4] = [========[]========]
P[5] = [========[]========]
P[6] = [========[]========]
P[7] = [========[]========]
P[8] = [========[]========]
P[9] = [========[]========]
P[10] = [========[]========]
P[11] = [========[]========]
P[12] = [========[]========]
P[13] = [========[]========]
P[14] = [========[]========]
P[15] = [========[]========]
P[16] = [========[]========]
P[17] = [========[]========]
P[18] = [========[]========]
P[19] = [========[]========]
P[20] = [========[]========]
P[21] = [========[]========]
P[22] = [========[]========]
P[23] = [========[]========]
P[24] = [========[]========]
P[25] = [========[]========]
P[26] = [========[]========]
P[27] = [========[]========]
P[28] = [========[]========]
P[29] = [========[]========]
P[30] = [========[]========]
local E = table.concat(P)
P = nil
local expected = 536599
local out, n, cap = {}, 0, 4096
local buf = {}
for pos = 1, #E - 3, 4 do
    local a = M[E:byte(pos)]
    local b = M[E:byte(pos + 1)]
    local c = M[E:byte(pos + 2)]
    local d = M[E:byte(pos + 3)]
    if not a or not b or not c or not d then error("corrupt payload") end
    local v = bor(lshift(a, 18), lshift(b, 12), lshift(c, 6), d)
    local b1 = band(rshift(v, 16), 255)
    local b2 = band(rshift(v, 8), 255)
    local b3 = band(v, 255)
    for j = 1, 3 do
        local group = (pos - 1) / 4
        local i = group * 3 + j - 1
        if i < expected then
            local k = key[(i % 96) + 1]
            local ch
            if j == 1 then ch = b1 elseif j == 2 then ch = b2 else ch = b3 end
            n = n + 1
            buf[n] = string.char(bxor(ch, k))
            if n >= cap then
                out[#out + 1] = table.concat(buf)
                buf = {}
                n = 0
            end
        end
    end
end
if n > 0 then out[#out + 1] = table.concat(buf) end
local source = table.concat(out)
if #source ~= expected then error("runtime size mismatch: " .. #source .. "/" .. expected, 0) end
local chunk, load_error = loadstring(source, "ENRIQUE_FREE_V23")
if not chunk then error(load_error, 0) end
chunk()
end)

if not _ok then
    warn("[ENRIQUE] startup failed: " .. tostring(_err))
    pcall(function()
        game:GetService("StarterGui"):SetCore("SendNotification", {Title="ENRIQUE ERROR", Text=tostring(_err):sub(1,180), Duration=10})
    end)
end
